import { ImageBackground, StyleSheet, Text, View } from 'react-native'
import React from 'react'
import { useNavigation } from '@react-navigation/native'

const HomeScreen1 = () => {
  const navigation = useNavigation()
  const image = { uri: 'https://firebasestorage.googleapis.com/v0/b/swapper-stu.appspot.com/o/Assets%2Fproducts-banner-image.png?alt=media&token=bfe79d05-c67c-4bf2-98f7-3dd80e1c1829' }

  return (
    <View style={styles.container}>
    <ImageBackground source={image} resizeMode="cover" style={styles.image}>
      <Text style={styles.text}>Lo que necesitas para tus estudios en un solo lugar</Text>
    </ImageBackground>
  </View>
  )
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  image: {
    flex: 1,
    justifyContent: 'center',
  },
  text: {
    flex: 1,
    top: '10%',
    left: '10%',
    width: '80%',
    color: 'black',
    fontSize: 42,
    lineHeight: 84,
    fontWeight: 'bold',
    textAlign: 'center',
  },
});

export default HomeScreen1
